import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.iXqqCa-C.js";const i="/images/misskey-privacy.webp",s="/images/misskey-mute-block.webp",l="/images/misskey-security.webp",p=JSON.parse('{"title":"设置与隐私","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/settings-privacy.md","filePath":"guide/misskey/settings-privacy.md","lastUpdated":1793076233000}'),o={name:"guide/misskey/settings-privacy.md"};function n(h,t,u,c,g,m){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="设置与隐私" tabindex="-1">设置与隐私 <a class="header-anchor" href="#设置与隐私" aria-label="Permalink to &quot;设置与隐私&quot;">​</a></h1><p>通过侧栏「设置」进入。左侧为设置分类，顶部搜索框可直接搜索设置项。</p><h2 id="个人资料" tabindex="-1">个人资料 <a class="header-anchor" href="#个人资料" aria-label="Permalink to &quot;个人资料&quot;">​</a></h2><ul><li>头像、横幅、昵称、个人简介（支持 <a href="/guide/misskey/mfm">MFM 语法</a> 和 #标签）、生日、所在地、语言。</li><li><strong>附加信息</strong>：最多 4 条「标签 + 内容」，以表格显示在主页。内容填 URL 且对方网页包含你的主页链接时，会显示已验证图标。</li><li><strong>被关注时显示的消息</strong>：别人关注你时向对方显示的短消息。</li><li><strong>接受表情回应</strong>：全部 / 仅点赞 / 仅限非敏感内容等。</li><li><strong>这是一个机器人账号</strong>、<strong>猫模式</strong>等标记。</li><li>佩戴<a href="/guide/misskey/achievements#头像挂件">头像挂件</a>。</li></ul><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td>关注请求需要批准</td><td>开启后别人关注你需要你同意（锁定账号）；只要帖子可见范围不是「仅关注者」，帖子本身仍对所有人可见</td></tr><tr><td>自动允许回关请求</td><td>锁定账号时，你关注的人申请关注你会自动通过</td></tr><tr><td>隐藏在线状态</td><td>不向他人显示在线状态</td></tr><tr><td>使账号可见</td><td>关闭后账号不出现在「发现」中</td></tr><tr><td>要求搜索引擎不索引该用户</td><td>请求搜索引擎不收录</td></tr><tr><td>拒绝接受生成式 AI 的学习</td><td>向爬虫声明拒绝 AI 训练</td></tr><tr><td>将回应设置为公开</td><td>他人可在你主页的「回应」标签看到你发出的回应</td></tr><tr><td>关注 / 关注者列表可见性</td><td>公开 / 仅关注者 / 私密</td></tr><tr><td>谁可以发起聊天</td><td>任何人 / 仅关注者 / 仅关注的人 / 仅相互关注 / 没有人</td></tr><tr><td>需要登录才能显示内容</td><td>你的帖子只对已登录用户显示</td></tr><tr><td>将过去的帖子设为仅关注者可见 / 私密</td><td>超过指定时长或早于指定日期的帖子自动变为仅关注者可见或仅自己可见；关闭后恢复原可见范围</td></tr></tbody></table><p>帖子默认可见范围在「偏好设置」中设置。</p><p><img src="'+i+'" alt="隐私设置"></p><h2 id="屏蔽与过滤" tabindex="-1">屏蔽与过滤 <a class="header-anchor" href="#屏蔽与过滤" aria-label="Permalink to &quot;屏蔽与过滤&quot;">​</a></h2><p>「设置 → 屏蔽与过滤」：</p><table tabindex="0"><thead><tr><th>项目</th><th>效果</th></tr></thead><tbody><tr><td>折叠关键词</td><td>命中的帖子折叠显示，点击可展开</td></tr><tr><td>屏蔽关键词</td><td>命中的帖子完全不显示</td></tr><tr><td>打码表情符号</td><td>指定的表情符号打码显示</td></tr><tr><td>已隐藏的用户（转发）</td><td>只隐藏该用户的转帖</td></tr><tr><td>已隐藏的用户</td><td>不再显示对方的帖子和通知，可设定隐藏时长</td></tr><tr><td>已屏蔽的用户</td><td>对方无法关注你、回应你或与你互动</td></tr></tbody></table><p>关键词数量上限由服务器策略决定。隐藏和屏蔽也可以在对方主页的「…」菜单中操作。</p><p><img src="'+s+'" alt="屏蔽与过滤"></p><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><ul><li>按类型设置接收范围：全部 / 关注中 / 关注者 / 相互关注 / 指定列表 / 不接收。</li><li>开启浏览器推送通知，可发送测试通知。</li><li>支持的类型见<a href="/guide/messages#通知类型">通知类型</a>。</li></ul><h2 id="邮箱" tabindex="-1">邮箱 <a class="header-anchor" href="#邮箱" aria-label="Permalink to &quot;邮箱&quot;">​</a></h2><p>绑定邮箱后可选择哪些事件发送邮件通知，以及是否接收服务器公告邮件。</p><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>修改密码</td><td>—</td></tr><tr><td>验证器</td><td>TOTP 两步验证，用验证器应用扫码绑定；设置完成后会给出一次性备用代码，请妥善保存</td></tr><tr><td>安全密钥或 Passkey</td><td>需先设置验证器才能注册；可开启「无密码登录」，只用安全密钥或 Passkey 登录</td></tr><tr><td>登录历史</td><td>查看近期登录记录</td></tr><tr><td>重新生成登录令牌</td><td>让所有已登录设备退出</td></tr></tbody></table><p><img src="'+l+'" alt="安全设置"></p><h2 id="服务连接与账户数据" tabindex="-1">服务连接与账户数据 <a class="header-anchor" href="#服务连接与账户数据" aria-label="Permalink to &quot;服务连接与账户数据&quot;">​</a></h2><ul><li><strong>服务连接</strong>：生成访问令牌，供 <a href="/guide/aliya-web">Aliya Web</a>、<a href="/guide/third-party">第三方应用</a>等外部程序使用；也可查看和撤销已授权的应用。</li><li><strong>账户数据</strong>：导出所有帖子、收藏的帖子、便签、关注列表、隐藏/屏蔽列表、列表、天线，导出完成后会收到通知，文件保存到网盘。导入功能是否可用由服务器策略决定。</li></ul><h2 id="多账号与配置文件" tabindex="-1">多账号与配置文件 <a class="header-anchor" href="#多账号与配置文件" aria-label="Permalink to &quot;多账号与配置文件&quot;">​</a></h2><ul><li>侧栏底部头像菜单可「添加账户」并在多个账号间切换。</li><li><strong>配置文件</strong>：客户端设置按设备保存为配置文件（如「PC」「手机」），不建议多设备共用同一配置文件；需要多设备同步的设置项可单独打开「设备间同步」。可以开启自动备份，防止设置丢失。</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><ul><li><strong>偏好设置</strong>：默认可见范围、敏感媒体显示方式、动画、数据节省模式、发帖与聊天行为等。</li><li><strong>表情符号调色板</strong>：自定义回应和发帖时的常用表情面板，见<a href="/guide/misskey/reactions">回应与表情符号</a>。</li><li><strong>网盘设置</strong>：见<a href="/guide/misskey/drive">网盘</a>。</li><li>界面、主题、提示音、插件：见<a href="/guide/misskey/ui-themes">界面、主题与小工具</a>。</li><li><strong>其他 → 永久注销账户</strong>：账号删除不可撤销，内容较多时需要一段时间，完成后会发邮件通知。</li></ul>',26)])])}const y=a(o,[["render",n]]);export{p as __pageData,y as default};
